SELECT 
FROM task
WHERE org_id = #{orgId}
  AND assignee_member_id = #{assigneeMemberId}
  AND status IN ('PENDING', 'IN_PROGRESS')
ORDER BY due_at ASC, id ASC

SELECT COUNT(*)
FROM task
WHERE org_id = #{orgId}
  AND assignee_member_id = #{assigneeMemberId}
  AND status IN ('PENDING', 'IN_PROGRESS')

SELECT COUNT(*)
FROM task
WHERE activity_id = #{activityId}
